        "ino" => Ok(vec![DetailField::Ino]),
        "nlink" => Ok(vec![DetailField::Nlink]),
        "typ" => Ok(vec![DetailField::Typ]),
        "perm" => Ok(vec![DetailField::Perm]),
        "oct" => Ok(vec![DetailField::Oct]),
        "user" => Ok(vec![DetailField::User]),
        "uid" => Ok(vec![DetailField::Uid]),
        "group" => Ok(vec![DetailField::Group]),
        "gid" => Ok(vec![DetailField::Gid]),
        "size" => Ok(vec![DetailField::Size]),
        "blocks" => Ok(vec![DetailField::Blocks]),
        "btime" => Ok(vec![DetailField::Btime]),
        "ctime" => Ok(vec![DetailField::Ctime]),
        "mtime" => Ok(vec![DetailField::Mtime]),
        "atime" => Ok(vec![DetailField::Atime]),
        "git" => Ok(vec![DetailField::Git]),
        "std" => Ok(DetailField::STD.to_vec()),
        "all" => Ok(DetailField::ALL.to_vec()),
        "none" => Ok(vec![]),
        _ => Err(invalid_value_err("--det <DETAILS>", v, DETAILS_POSSIBLE)),
    }
}

fn parse_bool(v: &str, flag: &str, possible: &[&str]) -> Result<bool, String> {
