fn invalid_value_err(flag: &str, v: &str, possible: &[&str]) -> String {
    let mut s = String::new();
    writeln!(&mut s, "error: invalid value '{}' for '{}'", v, flag).unwrap();
    writeln!(&mut s, "  [possible values: {}]", possible.join(", ")).unwrap();
    if let Some(sim) = find_similar(v, possible) {
        writeln!(&mut s).unwrap();
        writeln!(&mut s, "  tip: a similar value exists: '{}'", sim).unwrap();
    }
    writeln!(&mut s).unwrap();
    writeln!(&mut s, "For more information, try '--help'.").unwrap();
    s
}

fn find_similar(s: &str, possible: &[&str]) -> Option<String> {
    let mut best: Option<(usize, &str)> = None;
    for p in possible {
        let d = edit_distance(s, p);
        let max_d = (s.len().max(p.len())) / 3 + 1;
        if d <= max_d {
            if best.map_or(true, |(bd, _)| d < bd) {
                best = Some((d, *p));
            }
        }
    }
    best.map(|(_, p)| p.to_string())
}

fn edit_distance(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let (m, n) = (a.len(), b.len());
    let mut dp = vec![vec![0usize; n + 1]; m + 1];
    for i in 0..=m { dp[i][0] = i; }
    for j in 0..=n { dp[0][j] = j; }
    for i in 1..=m {
        for j in 1..=n {
            let cost = if a[i-1] == b[j-1] { 0 } else { 1 };
            dp[i][j] = (dp[i-1][j] + 1).min(dp[i][j-1] + 1).min(dp[i-1][j-1] + cost);
        }
    }
    dp[m][n]
}

pub fn parse(argv: &[String]) -> Result<ParseResult, String> {
    let mut args = Args::default();
    let mut paths: Vec<String> = vec![];
    let mut det_seen = false;
    let mut typ_seen = false;
    let mut sort_seen = false;

    let mut i = 1;
    let mut end_of_opts = false;
    while i < argv.len() {
        let a = &argv[i];
        if !end_of_opts && a == "--" {
            end_of_opts = true;
            i += 1;
            continue;
        }
        if !end_of_opts && a.starts_with('-') && a != "-" {
            // Parse option
            let (flag, maybe_val) = if let Some(eq) = a.find('=') {
                (a[..eq].to_string(), Some(a[eq+1..].to_string()))
            } else {
                (a.clone(), None)
            };

            // Expand short flags like "-d"
            let names: Vec<String> = if flag.starts_with("--") {
                vec![flag.clone()]
            } else {
                // Short. Could be -d value OR -dvalue. We'll handle both by first
                // trying full "-X" as a flag name.
                vec![flag.clone()]
            };

            let name = &names[0];
            // Helper to get the value (either after = or next arg)
            let take_value = |i: &mut usize, maybe_val: Option<String>| -> Result<String, String> {
                if let Some(v) = maybe_val {
                    Ok(v)
                } else {
                    *i += 1;
                    if *i >= argv.len() {
                        return Err(value_required_err(name));
                    }
                    Ok(argv[*i].clone())
                }
            };

            match name.as_str() {
                "-h" => return Ok(ParseResult::Help(help_text(false))),
                "--help" => return Ok(ParseResult::Help(help_text(true))),
                "-V" | "--version" => return Ok(ParseResult::Version(version_text())),
                "-d" | "--det" => {
                    let v = take_value(&mut i, maybe_val)?;
                    let fs = parse_detail(&v)?;
                    if !det_seen {
                        args.details.clear();
                        det_seen = true;
                    }
                    for f in fs {
                        if !args.details.contains(&f) {
                            args.details.push(f);
                        }
                    }
                    // If value was "none", clear.
                    if v == "none" {
                        args.details.clear();
                    }
                }
                "-H" | "--header" => {
                    let v = take_value(&mut i, maybe_val)?;
                    args.header = parse_bool(&v, "--header <HEADER>", HEADER_POSSIBLE)?;
                }
                "-u" | "--unit" => {
                    let v = take_value(&mut i, maybe_val)?;
                    args.unit = parse_unit(&v)?;
                }
                "-g" | "--grid" => {
                    let v = take_value(&mut i, maybe_val)?;
                    args.grid = parse_bool(&v, "--grid <GRID>", GRID_POSSIBLE)?;
                }
                "-D" | "--down" => {
                    let v = take_value(&mut i, maybe_val)?;
                    args.down = parse_bool(&v, "--down <DOWN>", DOWN_POSSIBLE)?;
                }
                "-i" | "--icon" => {
                    let v = take_value(&mut i, maybe_val)?;
                    args.icon = parse_bool(&v, "--icon <ICON>", ICON_POSSIBLE)?;
                }
                "-S" | "--suffix" => {
                    let v = take_value(&mut i, maybe_val)?;
                    args.suffix = parse_bool(&v, "--suffix <SUFFIX>", SUFFIX_POSSIBLE)?;
                }
                "-l" | "--sym" => {
                    let v = take_value(&mut i, maybe_val)?;
                    args.sym = parse_bool(&v, "--sym <SYM>", SYM_POSSIBLE)?;
                }
                "-c" | "--collapse" => {
                    let v = take_value(&mut i, maybe_val)?;
                    args.collapse = parse_bool(&v, "--collapse <COLLAPSE>", COLLAPSE_POSSIBLE)?;
                }
                "-a" | "--align" => {
                    let v = take_value(&mut i, maybe_val)?;
                    args.align = parse_bool(&v, "--align <ALIGN>", ALIGN_POSSIBLE)?;
                }
                "-t" | "--typ" => {
                    let v = take_value(&mut i, maybe_val)?;
                    let ts = parse_types(&v)?;
                    if !typ_seen {
                        args.types.clear();
                        typ_seen = true;
                    }
                    for t in ts {
                        if !args.types.contains(&t) {
                            args.types.push(t);
                        }
                    }
                    if v == "none" {
                        args.types.clear();
                    }
                }
                "-I" | "--imp" => {
                    let v = take_value(&mut i, maybe_val)?;
                    args.imp = v.parse::<i32>().map_err(|_| {
                        format!("error: invalid value '{}' for '--imp <IMP>': invalid digit found in string\n\nFor more information, try '--help'.\n", v)
                    })?;
                }
                "-e" | "--exclude" => {
                    let v = take_value(&mut i, maybe_val)?;
                    args.exclude = Some(v);
                }
                "-o" | "--only" => {
                    let v = take_value(&mut i, maybe_val)?;
                    args.only = Some(v);
                }
                "-s" | "--sort" => {
                    let v = take_value(&mut i, maybe_val)?;
                    let sb = parse_sort(&v)?;
                    if !sort_seen {
                        args.sort_bases.clear();
                        sort_seen = true;
                    }
                    if matches!(sb.field, SortField::None) {
                        args.sort_bases.clear();
                    } else {
                        args.sort_bases.push(sb);
                    }
                }
                _ => {
                    return Err(unexpected_arg_err(name));
                }
            }
            i += 1;
        } else {
            paths.push(a.clone());
            i += 1;
        }
    }

    if paths.is_empty() {
        paths.push(".".to_string());
    }
    args.paths = paths;
    Ok(ParseResult::Args(args))
}

fn value_required_err(flag: &str) -> String {
    let possible = match flag {
        "-d" | "--det" => DETAILS_POSSIBLE,
        "-H" | "--header" => HEADER_POSSIBLE,
        "-u" | "--unit" => UNIT_POSSIBLE,
        "-g" | "--grid" => GRID_POSSIBLE,
        "-D" | "--down" => DOWN_POSSIBLE,
        "-i" | "--icon" => ICON_POSSIBLE,
        "-S" | "--suffix" => SUFFIX_POSSIBLE,
        "-l" | "--sym" => SYM_POSSIBLE,
        "-c" | "--collapse" => COLLAPSE_POSSIBLE,
        "-a" | "--align" => ALIGN_POSSIBLE,
        "-t" | "--typ" => TYPES_POSSIBLE,
        "-s" | "--sort" => SORT_POSSIBLE,
        _ => &[],
    };
    let argname = match flag {
        "-d" | "--det" => "--det <DETAILS>",
        "-H" | "--header" => "--header <HEADER>",
        "-u" | "--unit" => "--unit <UNIT>",
        "-g" | "--grid" => "--grid <GRID>",
        "-D" | "--down" => "--down <DOWN>",
        "-i" | "--icon" => "--icon <ICON>",
        "-S" | "--suffix" => "--suffix <SUFFIX>",
        "-l" | "--sym" => "--sym <SYM>",
        "-c" | "--collapse" => "--collapse <COLLAPSE>",
        "-a" | "--align" => "--align <ALIGN>",
        "-t" | "--typ" => "--typ <TYPES>",
        "-I" | "--imp" => "--imp <IMP>",
        "-e" | "--exclude" => "--exclude <EXCLUDE>",
        "-o" | "--only" => "--only <ONLY>",
        "-s" | "--sort" => "--sort <SORT_BASES>",
        _ => flag,
    };
    let mut s = String::new();
    writeln!(&mut s, "error: a value is required for '{}' but none was supplied", argname).unwrap();
    if !possible.is_empty() {
        writeln!(&mut s, "  [possible values: {}]", possible.join(", ")).unwrap();
    }
    writeln!(&mut s).unwrap();
    writeln!(&mut s, "For more information, try '--help'.").unwrap();
    s
}

fn unexpected_arg_err(arg: &str) -> String {
    let mut s = String::new();
    writeln!(&mut s, "error: unexpected argument '{}' found", arg).unwrap();
    writeln!(&mut s).unwrap();
    writeln!(&mut s, "  tip: to pass '{}' as a value, use '-- {}'", arg, arg).unwrap();
    writeln!(&mut s).unwrap();
    writeln!(&mut s, "Usage: executable [OPTIONS] [PATHS]...").unwrap();
    writeln!(&mut s).unwrap();
    writeln!(&mut s, "For more information, try '--help'.").unwrap();
    s
}

pub fn version_text() -> String {
    "pls 0.0.1-beta.9\n".to_string()
}

pub fn help_text(long: bool) -> String {
    if long { help_long() } else { help_short() }
