        "group" => Ok(vec![DetailField::Group]),
        "gid" => Ok(vec![DetailField::Gid]),
        "size" => Ok(vec![DetailField::Size]),
        "blocks" => Ok(vec![DetailField::Blocks]),
        "btime" => Ok(vec![DetailField::Btime]),
        "ctime" => Ok(vec![DetailField::Ctime]),
        "mtime" => Ok(vec![DetailField::Mtime]),
        "atime" => Ok(vec![DetailField::Atime]),
