// Convert SystemTime to local calendar date (year, month, day, hour, minute, second)
// using /etc/localtime or TZ env var.

use std::fs;
use std::time::{SystemTime, UNIX_EPOCH};

pub struct Calendar {
    pub year: i32,
    pub month: u32,  // 1-12
    pub day: u32,    // 1-31
    pub hour: u32,
    pub minute: u32,
    pub second: u32,
}

static MONTH_NAMES: &[&str] = &["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

fn is_leap(y: i32) -> bool {
    (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

fn days_in_month(y: i32, m: u32) -> u32 {
    match m {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => if is_leap(y) { 29 } else { 28 },
        _ => 0,
    }
}

fn civil_from_days(days: i64) -> (i32, u32, u32) {
    // From Howard Hinnant's date algorithms.
    let days = days + 719468;
    let era = if days >= 0 { days / 146097 } else { (days - 146096) / 146097 };
    let doe = (days - era * 146097) as u64; // [0, 146096]
    let yoe = (doe - doe/1460 + doe/36524 - doe/146096) / 365; // [0, 399]
    let y = yoe as i64 + era * 400;
    let doy = doe - (365*yoe + yoe/4 - yoe/100); // [0, 365]
    let mp = (5*doy + 2)/153; // [0, 11]
    let d = (doy - (153*mp + 2)/5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    let y = if m <= 2 { y + 1 } else { y };
    (y as i32, m, d)
}

pub fn to_local(t: SystemTime) -> Calendar {
    let dur = t.duration_since(UNIX_EPOCH).unwrap_or_default();
    let secs = dur.as_secs() as i64;
    // Determine local offset from UTC.
    let offset = local_offset_seconds(secs);
    let local = secs + offset;
    let days = local.div_euclid(86400);
    let sod = local.rem_euclid(86400);
