// Lookup user name from UID and group name from GID using /etc/passwd and /etc/group.

use std::fs;
use std::sync::OnceLock;
use std::collections::HashMap;

fn load_passwd() -> HashMap<u32, String> {
    let mut m = HashMap::new();
    if let Ok(content) = fs::read_to_string("/etc/passwd") {
        for line in content.lines() {
            let parts: Vec<&str> = line.split(':').collect();
            if parts.len() >= 3 {
                if let Ok(uid) = parts[2].parse::<u32>() {
                    m.insert(uid, parts[0].to_string());
                }
            }
        }
    }
    m
}

fn load_group() -> HashMap<u32, String> {
    let mut m = HashMap::new();
    if let Ok(content) = fs::read_to_string("/etc/group") {
        for line in content.lines() {
            let parts: Vec<&str> = line.split(':').collect();
            if parts.len() >= 3 {
                if let Ok(gid) = parts[2].parse::<u32>() {
                    m.insert(gid, parts[0].to_string());
                }
            }
        }
    }
    m
}

pub fn user_name(uid: u32) -> String {
    static CACHE: OnceLock<HashMap<u32, String>> = OnceLock::new();
    let map = CACHE.get_or_init(load_passwd);
    map.get(&uid).cloned().unwrap_or_else(|| uid.to_string())
}

pub fn group_name(gid: u32) -> String {
    static CACHE: OnceLock<HashMap<u32, String>> = OnceLock::new();
    let map = CACHE.get_or_init(load_group);
    map.get(&gid).cloned().unwrap_or_else(|| gid.to_string())
}

pub fn current_uid() -> u32 {
    // syscall getuid on Linux x86_64 is 102. Avoid using libc.
    unsafe {
        let mut ret: i64;
        std::arch::asm!("syscall", in("rax") 102i64, lateout("rax") ret, out("rcx") _, out("r11") _);
        ret as u32
    }
}
