use crate::args::{DetailField, SizeUnit};

#[derive(Clone)]
pub struct Column {
    pub header: String,
    pub align_right: bool,
    pub cells: Vec<String>,   // Each entry may be pre-colored.
    pub visible_widths: Vec<usize>, // visible width for alignment
}

pub fn header_for(d: DetailField) -> &'static str {
    match d {
        DetailField::Dev => "Device",
        DetailField::Ino => "inode",
        DetailField::Nlink => "Link#",
        DetailField::Typ => "T",
        DetailField::Perm => "Permissions",
        DetailField::Oct => "SUGO",
        DetailField::User => "User",
        DetailField::Uid => "UID",
        DetailField::Group => "Group",
        DetailField::Gid => "GID",
        DetailField::Size => "Size",
        DetailField::Blocks => "Blocks",
        DetailField::Btime => "Created",
        DetailField::Ctime => "Changed",
        DetailField::Mtime => "Modified",
        DetailField::Atime => "Accessed",
        DetailField::Git => "Git",
    }
}

pub fn is_right_aligned(d: DetailField) -> bool {
    matches!(d, DetailField::Dev | DetailField::Ino | DetailField::Nlink
             | DetailField::Oct | DetailField::Uid | DetailField::Gid
             | DetailField::Size | DetailField::Blocks)
}

pub fn format_size(size: u64, unit: SizeUnit) -> String {
    match unit {
        SizeUnit::None => format!("{} B", size),
        SizeUnit::Binary => format_size_scaled(size, 1024, &["B", "KiB", "MiB", "GiB", "TiB", "PiB"]),
        SizeUnit::Decimal => format_size_scaled(size, 1000, &["B", "kB", "MB", "GB", "TB", "PB"]),
    }
}

fn format_size_scaled(size: u64, base: u64, units: &[&str]) -> String {
    let mut val = size as f64;
    let mut idx = 0usize;
    while val >= base as f64 && idx + 1 < units.len() {
        val /= base as f64;
        idx += 1;
    }
    format!("{:.1} {}", val, units[idx])
}
