use std::fs;
use std::io::{self, IsTerminal, Write};
use std::os::unix::fs::{FileTypeExt, MetadataExt, PermissionsExt};
use std::path::{Path, PathBuf};
use std::time::SystemTime;

use crate::args::{Args, DetailField, NodeType, SizeUnit, SortBase, SortField};
use crate::detail::{format_size, header_for, is_right_aligned};
use crate::icons;
use crate::time::{format_date, to_local};
use crate::users::{group_name, user_name};

const RESET: &str = "\x1b[0m";

pub struct Node {
    pub path: PathBuf,
    pub name: String, // filename only
    pub meta: fs::Metadata,
    pub link_target: Option<PathBuf>,
    pub link_valid: bool,
    pub hidden: bool,
    pub importance: i32,
}

fn cname_key(name: &str) -> String {
    name.trim_start_matches('.').to_lowercase()
}

fn ext_key(name: &str) -> String {
    if let Some(dot) = name.rfind('.') {
        if dot > 0 {
            return name[dot + 1..].to_lowercase();
        }
    }
    String::new()
}

fn category_order(n: &Node) -> u32 {
    let ft = n.meta.file_type();
    if ft.is_dir() {
        return 0;
    }
    if ft.is_symlink() {
        return 2;
    }
    if ft.is_fifo() || ft.is_socket() || ft.is_block_device() || ft.is_char_device() {
        return 3;
    }
    1 // regular files
}

pub fn run(args: Args) -> io::Result<()> {
    let use_color = io::stdout().is_terminal();

    // Separate paths into files and directories.
    let mut files: Vec<(String, Node)> = vec![];
    let mut dirs: Vec<(String, Vec<Node>)> = vec![];
    let mut any_error = false;

    // Process paths in order.
    let mut ordered: Vec<(bool, String)> = vec![]; // (is_dir, original path)
    for p in &args.paths {
        match fs::symlink_metadata(p) {
            Ok(m) => {
                if m.is_dir() {
                    ordered.push((true, p.clone()));
                } else {
                    ordered.push((false, p.clone()));
                }
            }
            Err(e) => {
                eprintln!("{}:\n\terror: {} (os error {})", p, e.to_string().split(" (os error").next().unwrap_or("").trim_end(), e.raw_os_error().unwrap_or(0));
                any_error = true;
            }
        }
    }

    // Load files first.
    for (is_dir, p) in &ordered {
        if !*is_dir {
            match load_node(Path::new(p), &args) {
                Ok(n) => files.push((p.clone(), n)),
                Err(e) => {
                    eprintln!("{}:\n\terror: {} (os error {})", p, e.to_string().split(" (os error").next().unwrap_or("").trim_end(), e.raw_os_error().unwrap_or(0));
                    any_error = true;
                }
            }
        }
    }
    // Load directories (list their contents).
    for (is_dir, p) in &ordered {
        if *is_dir {
            match load_dir(Path::new(p), &args) {
                Ok(ns) => dirs.push((p.clone(), ns)),
                Err(e) => {
                    eprintln!("{}:\n\terror: {} (os error {})", p, e.to_string().split(" (os error").next().unwrap_or("").trim_end(), e.raw_os_error().unwrap_or(0));
                    any_error = true;
                }
            }
        }
    }

    let multi = args.paths.len() > 1;

    let stdout = io::stdout();
    let mut out = stdout.lock();

    // Print files (not sorted, in argument order).
    if !files.is_empty() {
        let nodes: Vec<&Node> = files.iter().map(|(_, n)| n).collect();
        render_nodes(&mut out, &nodes, &args, use_color, false)?;
    }

    // Print directories.
    for (idx, (name, nodes)) in dirs.iter().enumerate() {
        let show_header = multi;
        if show_header || !files.is_empty() {
            writeln!(out)?;
        }
        if show_header {
            writeln!(out, "{}:", name)?;
        }
        let refs: Vec<&Node> = nodes.iter().collect();
        render_nodes(&mut out, &refs, &args, use_color, true)?;
        let _ = idx;
    }

    if any_error {
        // Non-fatal handling already printed to stderr.
    }
    Ok(())
}

fn load_node(p: &Path, _args: &Args) -> io::Result<Node> {
    let meta = fs::symlink_metadata(p)?;
    let name = p
        .file_name()
        .map(|f| f.to_string_lossy().into_owned())
        .unwrap_or_else(|| p.to_string_lossy().into_owned());
    let (link_target, link_valid) = if meta.file_type().is_symlink() {
        match fs::read_link(p) {
            Ok(t) => {
                let mut valid = true;
                if let Ok(_resolved) = fs::metadata(p) {
                    // metadata follows symlinks; if it succeeds, the link is valid.
                } else {
                    valid = false;
                }
                (Some(t), valid)
            }
            Err(_) => (None, false),
        }
    } else {
        (None, true)
    };
    let hidden = name.starts_with('.');
    let importance = compute_importance(&name);
    Ok(Node {
        path: p.to_path_buf(),
        name,
        meta,
        link_target,
        link_valid,
        hidden,
        importance,
    })
}

fn compute_importance(name: &str) -> i32 {
    // Approximate classification:
    //   README*, LICENSE*: 2
    //   CONTRIBUTING, Dockerfile, Makefile, Cargo.toml, package.json: 1
    //   .cache, .git, known noisy hidden: -1 to 0
    //   .DS_Store, __pycache__, node_modules: -2
    //   hidden dotfiles: 0
    //   others: 0
    let lower = name.to_ascii_lowercase();
    match lower.as_str() {
        ".ds_store" | "thumbs.db" | "__pycache__" => return -1,
        _ => {}
    }
    if lower.starts_with("readme") || lower.starts_with("license") {
        return 2;
    }
    if lower.starts_with("contributing")
        || lower.starts_with("changelog")
        || lower == "dockerfile"
        || lower == "makefile"
        || lower == "cargo.toml"
        || lower == "package.json"
    {
        return 1;
    }
    0
}

fn filter_hidden(importance: i32, cutoff: i32) -> bool {
    importance >= cutoff
}

fn load_dir(p: &Path, args: &Args) -> io::Result<Vec<Node>> {
    let mut nodes: Vec<Node> = vec![];
    for entry in fs::read_dir(p)? {
        let entry = entry?;
        let node = load_node(&entry.path(), args)?;
        if !filter_hidden(node.importance, args.imp) {
            continue;
        }
        if !type_matches(&node, &args.types) {
            continue;
        }
        if let Some(pat) = &args.exclude {
            if simple_match(&node.name, pat) { continue; }
        }
        if let Some(pat) = &args.only {
            if !simple_match(&node.name, pat) { continue; }
        }
        nodes.push(node);
    }
    sort_nodes(&mut nodes, &args.sort_bases);
    Ok(nodes)
}

fn type_matches(n: &Node, types: &[NodeType]) -> bool {
    if types.is_empty() { return false; }
    let ft = n.meta.file_type();
    for t in types {
        let ok = match t {
            NodeType::Dir => ft.is_dir(),
            NodeType::Symlink => ft.is_symlink(),
            NodeType::Fifo => ft.is_fifo(),
            NodeType::Socket => ft.is_socket(),
            NodeType::BlockDevice => ft.is_block_device(),
            NodeType::CharDevice => ft.is_char_device(),
            NodeType::File => ft.is_file(),
        };
        if ok { return true; }
    }
    false
}

fn simple_match(name: &str, pattern: &str) -> bool {
    // Basic regex-like matching: supports literal match, $ anchor end, ^ anchor start,
    // \. for literal dot. Fallback to substring.
    let mut pat = pattern;
    let anchored_start = pat.starts_with('^');
    if anchored_start { pat = &pat[1..]; }
    let anchored_end = pat.ends_with('$');
    if anchored_end { pat = &pat[..pat.len()-1]; }
    // Handle simple escaped sequences
    let pat_unescaped: String = {
        let mut s = String::new();
        let mut it = pat.chars().peekable();
        while let Some(c) = it.next() {
            if c == '\\' {
                if let Some(&nxt) = it.peek() {
                    s.push(nxt);
                    it.next();
                }
            } else {
                s.push(c);
            }
        }
        s
    };
    if anchored_start && anchored_end {
        return name == pat_unescaped;
    } else if anchored_start {
        return name.starts_with(&pat_unescaped);
    } else if anchored_end {
        return name.ends_with(&pat_unescaped);
    }
    name.contains(&pat_unescaped)
}

fn sort_nodes(nodes: &mut Vec<Node>, bases: &[SortBase]) {
    nodes.sort_by(|a, b| {
        for sb in bases {
            let ord = compare_field(a, b, sb.field);
            let ord = if sb.reverse { ord.reverse() } else { ord };
            if ord != std::cmp::Ordering::Equal {
                return ord;
            }
        }
        std::cmp::Ordering::Equal
    });
}

fn compare_field(a: &Node, b: &Node, f: SortField) -> std::cmp::Ordering {
    use std::cmp::Ordering::*;
    match f {
        SortField::Dev => a.meta.dev().cmp(&b.meta.dev()),
        SortField::Ino => a.meta.ino().cmp(&b.meta.ino()),
        SortField::Nlink => a.meta.nlink().cmp(&b.meta.nlink()),
        SortField::Typ => {
            let at = type_sort_key(&a.meta.file_type());
            let bt = type_sort_key(&b.meta.file_type());
            at.cmp(&bt)
        }
        SortField::Cat => category_order(a).cmp(&category_order(b)),
        SortField::User => user_name(a.meta.uid()).cmp(&user_name(b.meta.uid())),
        SortField::Uid => a.meta.uid().cmp(&b.meta.uid()),
        SortField::Group => group_name(a.meta.gid()).cmp(&group_name(b.meta.gid())),
        SortField::Gid => a.meta.gid().cmp(&b.meta.gid()),
        SortField::Size => a.meta.size().cmp(&b.meta.size()),
        SortField::Blocks => a.meta.blocks().cmp(&b.meta.blocks()),
        SortField::Btime => time_cmp(a.meta.created().ok(), b.meta.created().ok()),
        SortField::Ctime => a.meta.ctime().cmp(&b.meta.ctime()),
        SortField::Mtime => a.meta.mtime().cmp(&b.meta.mtime()),
        SortField::Atime => a.meta.atime().cmp(&b.meta.atime()),
        SortField::Name => a.name.cmp(&b.name),
        SortField::Cname => cname_key(&a.name).cmp(&cname_key(&b.name)),
        SortField::Ext => ext_key(&a.name).cmp(&ext_key(&b.name)),
        SortField::None => Equal,
    }
}

fn type_sort_key(ft: &fs::FileType) -> u8 {
    if ft.is_dir() { 0 }
    else if ft.is_file() { 1 }
    else if ft.is_symlink() { 2 }
    else if ft.is_fifo() { 3 }
    else if ft.is_socket() { 4 }
    else if ft.is_block_device() { 5 }
    else if ft.is_char_device() { 6 }
    else { 7 }
}

fn time_cmp(a: Option<SystemTime>, b: Option<SystemTime>) -> std::cmp::Ordering {
    match (a, b) {
        (Some(x), Some(y)) => x.cmp(&y),
        (Some(_), None) => std::cmp::Ordering::Greater,
        (None, Some(_)) => std::cmp::Ordering::Less,
        (None, None) => std::cmp::Ordering::Equal,
    }
}

// Visible width of a string that may contain ANSI escapes.
fn visible_width(s: &str) -> usize {
    let mut count = 0usize;
    let mut in_esc = false;
    for c in s.chars() {
        if in_esc {
            if c.is_ascii_alphabetic() {
                in_esc = false;
            }
            continue;
        }
        if c == '\x1b' {
            in_esc = true;
            continue;
        }
        count += char_width(c);
    }
    count
}

fn char_width(c: char) -> usize {
    // Treat most as 1. We won't worry about fullwidth for now.
    if (c as u32) < 0x20 { return 0; }
    1
}

fn render_nodes<W: Write>(out: &mut W, nodes: &[&Node], args: &Args, use_color: bool, _sorted: bool) -> io::Result<()> {
    if args.details.is_empty() {
        for n in nodes {
            let line = render_name_line(n, args, use_color);
            writeln!(out, "{}", line)?;
        }
        return Ok(());
    }

    // Detail view: build columns.
    let mut columns: Vec<(DetailField, Vec<String>, Vec<usize>)> = vec![];
    for d in &args.details {
        let mut cells: Vec<String> = vec![];
        let mut widths: Vec<usize> = vec![];
        for n in nodes {
            let cell = render_detail(n, *d, args, use_color);
            widths.push(visible_width(&cell));
            cells.push(cell);
        }
        columns.push((*d, cells, widths));
    }

    // Name column.
    let name_cells: Vec<String> = nodes.iter().map(|n| render_name_line(n, args, use_color)).collect();
    let name_widths: Vec<usize> = name_cells.iter().map(|s| visible_width(s)).collect();

    // Determine max width per column.
    let mut col_w: Vec<usize> = columns.iter().map(|(d, _, ws)| {
        let mut w = 0usize;
        for x in ws { if *x > w { w = *x; } }
        if args.header {
            let hw = header_for(*d).len();
            if hw > w { w = hw; }
        }
        w
    }).collect();

    // Header row.
    if args.header {
        let mut header_line = String::new();
        for (i, (d, _, _)) in columns.iter().enumerate() {
            let hdr = header_for(*d);
            let w = col_w[i];
            let cell = if is_right_aligned(*d) {
                format!("{:>width$}", hdr, width = w)
            } else {
                format!("{:<width$}", hdr, width = w)
            };
            if use_color {
                header_line.push_str("\x1b[1;4;3m");
                header_line.push_str(&cell);
                header_line.push(' ');
                header_line.push_str(RESET);
            } else {
                header_line.push_str(&cell);
                header_line.push(' ');
            }
        }
        if use_color {
            header_line.push_str("\x1b[1;4;3m");
            header_line.push_str("Name");
            header_line.push_str(RESET);
        } else {
            header_line.push_str("Name");
        }
        writeln!(out, "{}", header_line)?;
    }

    // Data rows.
    for (ri, n) in nodes.iter().enumerate() {
        let mut line = String::new();
        for (i, (d, cells, widths)) in columns.iter().enumerate() {
            let cell = &cells[ri];
            let w = col_w[i];
            let cw = widths[ri];
            let pad = if w > cw { w - cw } else { 0 };
            if is_right_aligned(*d) {
                for _ in 0..pad { line.push(' '); }
                line.push_str(cell);
            } else {
                line.push_str(cell);
                for _ in 0..pad { line.push(' '); }
            }
            line.push(' ');
        }
        line.push_str(&name_cells[ri]);
        let _ = n;
        writeln!(out, "{}", line)?;
    }

    Ok(())
}

fn render_name_line(n: &Node, args: &Args, use_color: bool) -> String {
    let meta = &n.meta;
    let ft = meta.file_type();
    let is_dir = ft.is_dir();
    let is_link = ft.is_symlink();
    let is_fifo = ft.is_fifo();
    let is_exec = (meta.mode() & 0o111) != 0 && ft.is_file();
    let mut s = String::new();

    let icon = if args.icon {
        icons::icon_for(&n.name, is_dir, is_link, is_fifo, is_exec).unwrap_or(" ")
    } else {
        ""
    };

    // Color for the icon + name.
    let name_color: Option<&'static str> = if is_link {
        None
    } else if is_dir {
        Some("\x1b[34m") // blue
    } else {
        name_color_for(&n.name)
    };

    let dim = n.hidden || n.importance < args.imp.max(0);
    let readonly_name = (n.name.eq_ignore_ascii_case("readme")
        || n.name.to_ascii_lowercase().starts_with("readme."))
        && !is_dir;

    // Icon rendering
    if args.icon {
        if use_color {
            if dim { s.push_str("\x1b[2m"); }
            if let Some(c) = name_color { s.push_str(c); }
            s.push_str(icon);
            s.push(' ');
            if name_color.is_some() || dim { s.push_str(RESET); }
        } else {
            s.push_str(icon);
            s.push(' ');
        }
        s.push(' ');
    }

    // Alignment: if hidden name starts with '.', the dot is displayed separately (dim).
    // If visible and args.align, add an extra space to align with the position after dot.
    if n.hidden && n.name.starts_with('.') {
        // "dot" part, then rest of name.
        let rest = &n.name[1..];
        if use_color {
            s.push_str("\x1b[2m.\x1b[0m");
            // color + italic/underline for name
            let italic = is_dir && is_empty_dir(&n.path);
            if dim { s.push_str("\x1b[2m"); }
            if readonly_name { s.push_str("\x1b[4m"); }
            if italic {
                if let Some(c) = name_color { s.push_str(c); s.push_str("\x1b[3m"); } else { s.push_str("\x1b[3m"); }
            } else if let Some(c) = name_color { s.push_str(c); }
            s.push_str(rest);
            s.push_str(RESET);
        } else {
            s.push('.');
            s.push_str(rest);
        }
    } else {
        if args.align && !n.hidden {
            s.push(' ');
        }
        let italic = is_dir && is_empty_dir(&n.path);
        if use_color {
            let mut style = String::new();
            if dim { style.push_str("\x1b[2m"); }
            if readonly_name { style.push_str("\x1b[4m"); }
            if italic { style.push_str("\x1b[3m"); }
            if let Some(c) = name_color { style.push_str(c); }
            s.push_str(&style);
            s.push_str(&n.name);
            if !style.is_empty() { s.push_str(RESET); }
        } else {
            s.push_str(&n.name);
        }
    }

    // Suffix
    if args.suffix {
        if is_dir {
            if use_color {
                let c = name_color.unwrap_or("");
                s.push_str("\x1b[2");
                if !c.is_empty() { s.push(';'); s.push_str(&c[2..c.len()-1]); }
                s.push('m');
                s.push('/');
                s.push_str(RESET);
            } else {
                s.push('/');
            }
        } else if is_link {
            if use_color { s.push_str("\x1b[2m@\x1b[0m"); } else { s.push('@'); }
        } else if is_fifo {
            if use_color { s.push_str("\x1b[2m|\x1b[0m"); } else { s.push('|'); }
        }
    }

    // Symlink target
    if is_link && args.sym {
        if let Some(target) = &n.link_target {
            let tgt_str = target.to_string_lossy();
            if use_color {
                s.push(' ');
                s.push_str("\x1b[35m\u{f0054}\x1b[0m "); // arrow
                s.push_str(&tgt_str);
            } else {
                s.push(' ');
                s.push_str("\u{f0054} ");
                s.push_str(&tgt_str);
            }
        }
    }

    s
}

fn is_empty_dir(p: &Path) -> bool {
    if let Ok(mut it) = fs::read_dir(p) {
        it.next().is_none()
    } else {
        false
    }
}

fn name_color_for(name: &str) -> Option<&'static str> {
    // Specific name-based colors.
    let lower = name.to_ascii_lowercase();
    match lower.as_str() {
        ".gitignore" | ".gitmodules" | ".gitattributes" => return None,
        _ => {}
    }
    if let Some(dot) = name.rfind('.') {
        let ext = &name[dot+1..].to_ascii_lowercase();
        return match ext.as_str() {
            "rs" => Some("\x1b[91m"),
            _ => None,
        };
    }
    None
}

fn render_detail(n: &Node, d: DetailField, args: &Args, use_color: bool) -> String {
    let m = &n.meta;
    match d {
        DetailField::Dev => format!("{}", m.dev()),
        DetailField::Ino => format!("{}", m.ino()),
        DetailField::Nlink => format!("{}", m.nlink()),
        DetailField::Typ => typ_letter(m, use_color),
        DetailField::Perm => perm_string(m, use_color),
        DetailField::Oct => format!("{:04o}", m.mode() & 0o7777),
        DetailField::User => {
            let name = user_name(m.uid());
            if use_color {
                let c = if m.uid() == crate::users::current_uid() { "\x1b[1;34m" } else { "\x1b[2m" };
                format!("{}{}{}", c, name, RESET)
            } else { name }
        }
        DetailField::Uid => format!("{}", m.uid()),
        DetailField::Group => {
            let name = group_name(m.gid());
            if use_color {
                format!("\x1b[2m{}{}", name, RESET)
            } else { name }
        }
        DetailField::Gid => format!("{}", m.gid()),
        DetailField::Size => {
            if m.file_type().is_dir() { return String::new(); }
            let s = format_size(m.size(), args.unit);
            // Format to width: value.1f with 5-char right align, then unit in 3-char right.
            let (val, unit) = s.rsplit_once(' ').unwrap_or((&s, ""));
            if use_color {
                format!("\x1b[1m{:>5}\x1b[0m \x1b[2m{:>3}\x1b[0m", val, unit)
            } else {
                format!("{:>5} {:>3}", val, unit)
            }
        }
        DetailField::Blocks => {
            if m.file_type().is_dir() { return String::new(); }
            format!("{}", m.blocks())
        }
        DetailField::Btime => date_cell(m.created().ok(), use_color),
        DetailField::Ctime => date_cell(Some(systime_from_secs(m.ctime())), use_color),
        DetailField::Mtime => date_cell(Some(systime_from_secs(m.mtime())), use_color),
        DetailField::Atime => date_cell(Some(systime_from_secs(m.atime())), use_color),
        DetailField::Git => String::new(),
    }
}

fn systime_from_secs(secs: i64) -> SystemTime {
    if secs >= 0 {
        std::time::UNIX_EPOCH + std::time::Duration::from_secs(secs as u64)
    } else {
        std::time::UNIX_EPOCH - std::time::Duration::from_secs((-secs) as u64)
    }
}

fn date_cell(t: Option<SystemTime>, use_color: bool) -> String {
    let Some(t) = t else { return String::new(); };
    let cal = to_local(t);
    let full = format_date(&cal);
    // "2024-Jan-01 12:00am"
    // Color the date prefix (YYYY-MMM-DD) bold yellow.
    if let Some(pos) = full.find(' ') {
        if use_color {
            format!("\x1b[1;33m{}\x1b[0m {}", &full[..pos], &full[pos+1..])
        } else {
            full
        }
    } else {
        full
    }
}

fn typ_letter(m: &fs::Metadata, use_color: bool) -> String {
    let ft = m.file_type();
    let ch = if ft.is_dir() { 'd' }
        else if ft.is_symlink() { 'l' }
        else if ft.is_fifo() { 'p' }
        else if ft.is_socket() { 's' }
        else if ft.is_block_device() { 'b' }
        else if ft.is_char_device() { 'c' }
        else { 'f' };
    if use_color {
        match ch {
            'd' => format!("\x1b[34m{}\x1b[0m", ch),
            'f' => format!("\x1b[2m{}\x1b[0m", ch),
            _ => format!("{}", ch),
        }
    } else {
        format!("{}", ch)
    }
}

fn perm_string(m: &fs::Metadata, use_color: bool) -> String {
    let mode = m.mode();
    // Build user, group, other triplets
    let mut s = String::new();
    let triplets = [(mode >> 6) & 0o7, (mode >> 3) & 0o7, mode & 0o7];
    let specials = [(mode >> 11) & 1, (mode >> 10) & 1, (mode >> 9) & 1]; // suid, sgid, sticky
    for (i, t) in triplets.iter().enumerate() {
        if i > 0 { s.push(' '); }
        // r
        if t & 0o4 != 0 {
            if use_color { s.push_str("\x1b[33mr\x1b[0m"); } else { s.push('r'); }
        } else {
            if use_color { s.push_str("\x1b[2m-\x1b[0m"); } else { s.push('-'); }
        }
        // w
        if t & 0o2 != 0 {
            if use_color { s.push_str("\x1b[31mw\x1b[0m"); } else { s.push('w'); }
        } else {
            if use_color { s.push_str("\x1b[2m-\x1b[0m"); } else { s.push('-'); }
        }
        // x with special bits
        let x = t & 0o1 != 0;
        let special = specials[i] != 0;
        let ch: char = match (x, special, i) {
            (true, true, 0) => 's',
            (true, true, 1) => 's',
            (true, true, 2) => 't',
            (false, true, 0) => 'S',
            (false, true, 1) => 'S',
            (false, true, 2) => 'T',
            (true, false, _) => 'x',
            (false, false, _) => '-',
        };
        if ch == '-' {
            if use_color { s.push_str("\x1b[2m-\x1b[0m"); } else { s.push('-'); }
        } else if ch == 'x' {
            if use_color { s.push_str("\x1b[32mx\x1b[0m"); } else { s.push('x'); }
        } else {
            if use_color { s.push_str("\x1b[32m"); s.push(ch); s.push_str(RESET); } else { s.push(ch); }
        }
    }
    s
}
