        s.push(' ');
    }'''
new = '''    // Icon rendering: emit the icon (or a single-cell placeholder) followed by one space.
    // The icon and trailing space are inside a single color/dim span so that empty-icon
    // rendering uses two contiguous dim spaces for hidden files.
    if args.icon {
        if use_color {
            if dim { s.push_str("\\x1b[2m"); }
            if let Some(c) = name_color { s.push_str(c); }
            s.push_str(icon);
            s.push(' ');
            if name_color.is_some() || dim { s.push_str(RESET); }
        } else {
            s.push_str(icon);
            s.push(' ');
        }
    }'''
assert old in t
t = t.replace(old, new)
with open('src/render.rs', 'w') as f:
    f.write(t)
